    return [x * 2 for x in data]

def aggregate(data: list) -> dict:
    if not data:
        return {"count": 0, "total": 0}
    return {"count": len(data), "total": sum(data)}

def report(data: list) -> str:
    if data is None:
        return "count=0 total=0"
